/// <summary>
/// Parameters for executing the environment data setup.
/// </summary>
[DataContractAttribute]
class OLK_EnvironmentDataSetupExecuteContract implements SysOperationValidatable
{
    OLK_EdsEnvironmentId    environmentId;
    NoYesId                 executeData;
    NoYesId                 executeCode;
    NoYesId                 executeSql;
}

Method.Source:
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@OLK_EDSLabel:EnvironmentId")),
    SysOperationHelpTextAttribute(literalStr("@OLK_EDSLabel:EnvironmentIdHelp")),
    SysOperationDisplayOrderAttribute('1')
]
public OLK_EdsEnvironmentId parmEnvironmentId(OLK_EdsEnvironmentId _environmentId = environmentId)
{
    environmentId = _environmentId;

    return environmentId;
}

[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@OLK_EDSLabel:ExecuteData")),
    SysOperationHelpTextAttribute(literalStr("@OLK_EDSLabel:ExecuteDataHelp")),
    SysOperationDisplayOrderAttribute('2')
]
public NoYesId parmExecuteData(NoYesId _executeData = executeData)
{
