public boolean validate()
{
    if (!environmentId)
    {
        return checkFailed("@OLK_EDSLabel:EnvironmentIdEmpty");
    }

    if (!OLK_EnvironmentDataSetupTable::exist(environmentId))
    {
        return checkFailed(strFmt("@OLK_EDSLabel:EnvironmentNotFound", environmentId));
    }

    return true;
}
